<script lang="ts">const { onclick, children } = $props();
const handleClick = $derived.by(() => {
    return onclick
        ? (event) => {
            event.preventDefault();
            event.stopPropagation();
            onclick();
        }
        : undefined;
});
export {};
</script>

<button type="button" class="jse-tag" class:disabled={!onclick} onclick={handleClick}>
  {@render children?.()}
</button>

